effect.shader:
void main(){
vec2 r=acScreenSize, p=((acScreenNorm*r+acScreenNorm*r-r)/r.y)*scale; float t=time*speed,a=0.0,l=0.0,v=0.0;
for(int i=1;i<6;i++){ float fi=float(i); a=cos(atan(p.y,p.x)*2.0); l=abs(fi-length(p)); v+=a*l; float q=t+a; p=p*mat2(cos(q),cos(q+11.0),cos(q+22.0),cos(q))+vec2(a,l); }
vec3 pattern=abs(sin(v*vec3(0.3,0.2,0.1)))*vec3(1.0,0.72,0.18)*intensity; vec3 src=texture2DCv(inputImg.texture,acScreenNorm).rgb;
gl_FragColor=vec4(mix(min(pattern,vec3(1.0)),src,sourceMix),1.0);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
